// --- FUNCTION TO UPDATE UI ---
function updatePlayerCard(cardId, labelId, inlineId, degree, relationship) {
    // Update the Degree Text (Label and Paragraph)
    document.getElementById(labelId).textContent = degree;
    document.getElementById(inlineId).textContent = degree;

    // Update the Visual Class (Color)
    const card = document.getElementById(cardId);
    
    // Logic: If relationship is 'same', we often style it as 'you' 
    // (based on your previous code logic), otherwise use 'near' or 'far'.
    let cssClass = relationship;
    if (relationship === 'same') {
        cssClass = 'you'; 
    }
    
    // Reset class to base 'player' then add specific class
    card.className = 'player'; 
    if (cssClass) {
        card.classList.add(cssClass);
    }
}

