document.addEventListener('keydown', function(e) {
  // Key codes: 32=Space, 37=Left, 38=Up, 39=Right, 40=Down
  // Prevent default scrolling for arrows and spacebar
  if([32, 37, 38, 39, 40].indexOf(e.keyCode) > -1) {
      e.preventDefault();
  }

  if (gameOver) return;

  // left and right arrow keys (move)
  if (e.which === 37 || e.which === 39) {
    const col = e.which === 37 ? tetromino.col - 1 : tetromino.col + 1;
    if (isValidMove(tetromino.matrix, tetromino.row, col)) {
      tetromino.col = col;
    }
  }

  // up arrow key (rotate)
  if (e.which === 38) {
    const matrix = rotate(tetromino.matrix);
    if (isValidMove(matrix, tetromino.row, tetromino.col)) {
      tetromino.matrix = matrix;
    }
  }

  // down arrow key (soft drop)
  if (e.which === 40) {
    const row = tetromino.row + 1;

    // If moving down one row hits something, place the piece immediately
    if (!isValidMove(tetromino.matrix, row, tetromino.col)) {
      tetromino.row = row - 1; // Keep it at the current valid row
      placeTetromino();
      return;
    }

    // Otherwise, move it down
    tetromino.row = row;
    // Reset the automatic drop counter so it doesn't instantly drop again
    count = 0; 
  }
});

