// Start Countdown Timer
function startTimer() {
    gameTimer = setInterval(() => {
        timeLeft--;
        timerDisplay.textContent = timeLeft;
        if (timeLeft <= 0) {
            clearInterval(gameTimer);
            showGameOver('¡TIEMPO AGOTADO!');
        }
    }, 1000);
}

function getRandomInt(min, max) {
  min = Math.ceil(min);
  max = Math.floor(max);
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const tetrominoSequence = [];
function generateSequence() {
  const sequence = ['I', 'J', 'L', 'O', 'S', 'T', 'Z'];
  while (sequence.length) {
    const rand = getRandomInt(0, sequence.length - 1);
    tetrominoSequence.push(sequence.splice(rand, 1)[0]);
  }
}

function getNextTetromino() {
  if (tetrominoSequence.length === 0) generateSequence();
  const name = tetrominoSequence.pop();
  const matrix = tetrominos[name];
  const col = playfield[0].length / 2 - Math.ceil(matrix[0].length / 2);
  const row = name === 'I' ? -1 : -2;
  return { name: name, matrix: matrix, row: row, col: col };
}

function rotate(matrix) {
  const N = matrix.length - 1;
  return matrix.map((row, i) => row.map((val, j) => matrix[N - j][i]));
}

function isValidMove(matrix, cellRow, cellCol) {
  for (let row = 0; row < matrix.length; row++) {
    for (let col = 0; col < matrix[row].length; col++) {
      if (matrix[row][col] && (
          cellCol + col < 0 || cellCol + col >= playfield[0].length ||
          cellRow + row >= playfield.length || playfield[cellRow + row][cellCol + col])
        ) return false;
    }
  }
  return true;
}

function placeTetromino() {
  for (let row = 0; row < tetromino.matrix.length; row++) {
    for (let col = 0; col < tetromino.matrix[row].length; col++) {
      if (tetromino.matrix[row][col]) {
        if (tetromino.row + row < 0) {
          clearInterval(gameTimer);
          return showGameOver('¡TABLERO LLENO!');
        }
        playfield[tetromino.row + row][tetromino.col + col] = tetromino.name;
      }
    }
  }

  // Check for line clears
  let linesCleared = 0;
  for (let row = playfield.length - 1; row >= 0; ) {
    if (playfield[row].every(cell => !!cell)) {
        linesCleared++;
      for (let r = row; r >= 0; r--) {
        for (let c = 0; c < playfield[r].length; c++) {
          playfield[r][c] = playfield[r-1][c];
        }
      }
    } else {
      row--;
    }
  }

  // Only award points for cleared lines (100 pts per line)
  if (linesCleared > 0) {
      score += (linesCleared * 100);
      scoreFeedback.innerHTML = score;
  }

  tetromino = getNextTetromino();
}

function generateLeaderboard() {
    const competitors = [
        { name: userDegree, points: score, isUser: true }, 
        { name: "Ing. Comercial", points: getRandomInt(0, 3) * 100, isUser: false },
        { name: "Psicología", points: getRandomInt(0, 3) * 100, isUser: false },
        { name: "Derecho", points: getRandomInt(0, 3) * 100, isUser: false }
    ];
    
    const uniqueCompetitors = competitors.filter((v, i, a) => a.findIndex(t => (t.name === v.name)) === i);
    uniqueCompetitors.sort((a, b) => b.points - a.points);

    uniqueCompetitors.forEach((comp, index) => {
        const li = document.createElement('li');
        li.style.padding = "10px";
        li.style.marginBottom = "5px";
        li.style.borderRadius = "5px";
        li.style.display = "flex";
        li.style.justifyContent = "space-between";
        
        if (comp.isUser) {
            li.style.backgroundColor = "#EAF3F5"; 
            li.style.border = "1px solid #397893FF";
            li.style.fontWeight = "bold";
        } else {
            li.style.backgroundColor = "#f9f9f9";
            li.style.border = "1px solid #eee";
        }

        li.innerHTML = `<span>${index + 1}. ${comp.name}</span> <span>${comp.points} pts</span>`;
        rankingList.appendChild(li);
    });
}

