  // Función para determinar la relación
  function determineRelationship(uUni, uDeg, oUni, oDeg) {
      const sameUni = (uUni === oUni);
      const sameDeg = (uDeg === oDeg);

      if (sameUni && sameDeg) {
          return "you";        // Misma U, Misma Carrera
      } else if (sameUni && !sameDeg) {
          return "nearClose";  // Misma U, Distinta Carrera
      } else if (!sameUni && sameDeg) {
          return "nearFar";    // Distinta U, Misma Carrera
      } else {
          return "far";        // Distinta U, Distinta Carrera
      }
  }

